/// <summary>
/// The <c>METBulkFreeTextInvoiceWorkflowSubmissionSubTaskContract</c> class for sub task batch job.
/// </summary>
/// Added for CFR4 bulk approval AR invoice.
[DataContractAttribute]
class METBulkFreeTextInvoiceWorkflowSubmissionSubTaskContract
{
    RefRecId                    startRefRecId;
    RefRecId                    endRefRecId;
    container                   queryData;

}

Method.Source:
/// <summary>
/// Set the start recId of the thread.
/// </summary>
/// <param name = "_startRefRecId">Contains start recId.</param>
/// <returns>Return thread start RecId</returns>
[DataMember]
public RefRecId parmStartRefRecId(RefRecId _startRefRecId = startRefRecId)
{
    startRefRecId = _startRefRecId;

    return startRefRecId;
}

/// <summary>
/// Set the end recId of the thread.
/// </summary>
/// <param name = "_endRefRecId">Contains end recId.</param>
/// <returns>Return thread end RecId</returns>
[DataMember]
public RefRecId parmEndRefRecId(RefRecId _endRefRecId = endRefRecId)
{
    endRefRecId = _endRefRecId;

    return endRefRecId;
}

/// <summary>
/// Contains query filter.
/// </summary>
/// <param name = "_queryData">Contains query filter.</param>
/// <returns>Return query.</returns>
[DataMember]
public container parmQueryFilter(container _queryData = queryData)
{
    queryData = _queryData;

    return queryData;
}
